import{_ as e,o as a,c as s,aa as o}from"./chunks/framework.oWfRcsIL.js";const g=JSON.parse('{"title":"Safety controls","description":"Permission modes, approvals, Pause and Stop hunting.","frontmatter":{"title":"Safety controls","description":"Permission modes, approvals, Pause and Stop hunting."},"headers":[],"relativePath":"getting-started/safety-controls.md","filePath":"getting-started/safety-controls.md"}'),n={name:"getting-started/safety-controls.md"};function i(r,t,l,h,c,d){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="safety-controls" tabindex="-1">Safety controls <a class="header-anchor" href="#safety-controls" aria-label="Permalink to &quot;Safety controls&quot;">​</a></h1><p>The <a href="/legal/scope">scope</a> is the hard boundary: agents can never reach an out-of-scope host. Within the scope, these controls decide how much the agents may do without asking you, and how you stop them.</p><h2 id="permission-modes" tabindex="-1">Permission modes <a class="header-anchor" href="#permission-modes" aria-label="Permalink to &quot;Permission modes&quot;">​</a></h2><p>Every project has a <strong>Permission mode</strong>. It decides which agent actions need your approval.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Bypass approvals</strong></td><td>In-scope actions run without asking.</td><td>You trust the scope and want an uninterrupted run, typically on a staging system.</td></tr><tr><td><strong>Auto-classify actions</strong> (default)</td><td>Agents run normal actions on their own. An action that the model&#39;s safety classifier flags as risky is held until you decide.</td><td>The usual choice: you are only asked about risky actions.</td></tr><tr><td><strong>Approve flagged actions</strong></td><td>The strictest mode: flagged actions always wait for your decision.</td><td>Sensitive targets where you want to review risky actions yourself. Expect many approval requests.</td></tr></tbody></table><p>In every mode, an action that targets an out-of-scope host is never executed silently; it becomes an approval request.</p><p>Depending on the model, <strong>Auto-classify</strong> can still produce many approval requests (models differ in how much they flag). If that happens on a staging system, switching to <strong>Bypass approvals</strong> is usually the right answer.</p><div class="warning custom-block"><p class="custom-block-title">Bypass approvals is your decision</p><p>With <strong>Bypass approvals</strong>, nobody reviews the agents&#39; actions before they run. Every in-scope action is executed, including actions that change or delete data, lock accounts or put load on the system. Choosing this mode means you accept the impact of all those actions on the target, just as if you had approved each one yourself.</p><p>Only choose it if the system owner has agreed to this kind of testing and the target can tolerate it, typically a staging system that can be reset. The scope boundary still applies: out-of-scope hosts remain unreachable.</p></div><h3 id="changing-the-mode-during-a-run" tabindex="-1">Changing the mode during a run <a class="header-anchor" href="#changing-the-mode-during-a-run" aria-label="Permalink to &quot;Changing the mode during a run&quot;">​</a></h3><p>You can change the mode at any time on the <strong>Overview</strong> tab (<strong>Apply mode</strong>).</p><ul><li>Loosening the mode (for example to <strong>Bypass approvals</strong>) applies immediately, also to agents that are already running.</li><li>Tightening the mode applies to agents that start afterwards. Agents that are already running keep the looser mode until they finish. Pause and resume the project if the stricter mode must apply to everyone at once.</li></ul><h2 id="approvals" tabindex="-1">Approvals <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;Approvals&quot;">​</a></h2><p>When an agent needs your decision, the workspace shows an approval request with the agent, the action and its reason.</p><ul><li><strong>Allow once</strong> lets this single action run.</li><li><strong>Allow &amp; add host</strong> (for a host that is out of scope) lets the action run and adds the host to the project&#39;s scope permanently. Only use it if your <a href="/legal/authorization">authorization</a> covers that host.</li><li><strong>Deny</strong> blocks the action. The agent continues with something else.</li></ul><p>An approval request that nobody answers is denied automatically after about 10 minutes. Only that single action is denied; the run continues.</p><div class="warning custom-block"><p class="custom-block-title">You are responsible for what you allow</p><p>An approval is a decision you make on behalf of the test. When you allow an action, you take responsibility for its effect on the target, including data changes, locked accounts, triggered emails and load. When you add a host, you confirm that your <a href="/legal/authorization">authorization</a> covers it.</p><p>Read the action and its reason before you decide. If you cannot judge the impact, choose <strong>Deny</strong>: the agent continues with other tests, and you lose at most that single action.</p></div><p>The <strong>Approvals</strong> button in the workspace header shows all past decisions, including who decided and when.</p><h2 id="pause-and-resume" tabindex="-1">Pause and Resume <a class="header-anchor" href="#pause-and-resume" aria-label="Permalink to &quot;Pause and Resume&quot;">​</a></h2><p><strong>Pause</strong> stops all agents of the project. <strong>Resume</strong> continues the run where it stopped; agents pick up their work where they left off. Use Pause whenever you need the agents to stop for a while, for example when the system owner reports a problem.</p><h2 id="stop-hunting" tabindex="-1">Stop hunting <a class="header-anchor" href="#stop-hunting" aria-label="Permalink to &quot;Stop hunting&quot;">​</a></h2><p><strong>Stop hunting</strong> ends the testing for good. Use it when the <a href="/getting-started/pentest-not-a-scan">time box</a> is over.</p><ul><li>Hunting agents that are running or waiting are aborted.</li><li>Every test that has not run yet is marked as skipped.</li><li>Findings that already exist are still verified, reported and illustrated.</li><li>The project then finishes as <strong>completed with gaps</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Stop hunting cannot be undone</p><p>Hunting cannot be resumed after Stop hunting. If you only want to stop for now and continue later, use <strong>Pause</strong> instead.</p></div><h2 id="if-something-goes-wrong-on-the-target" tabindex="-1">If something goes wrong on the target <a class="header-anchor" href="#if-something-goes-wrong-on-the-target" aria-label="Permalink to &quot;If something goes wrong on the target&quot;">​</a></h2><p>If the target shows problems during a run (errors, high load, unexpected data changes):</p><ol><li>Press <strong>Pause</strong>. All agents stop.</li><li>Check the <strong>Agents</strong> tab to see which agents were running and what they did.</li><li>Clarify the problem with the system owner. If needed, narrow the scope with <strong>Edit scope</strong> or tighten the permission mode.</li><li>Press <strong>Resume</strong> to continue, or <strong>Stop hunting</strong> to end the test with the findings found so far.</li></ol><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I chose a permission mode that fits the target (staging or production).</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> If I use <strong>Bypass approvals</strong>, I accept the impact of every in-scope action the agents take.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I only allow actions whose impact I can judge and accept.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I will be available to answer approval requests during the run, or I chose <strong>Bypass approvals</strong>.</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> I know the difference between <strong>Pause</strong> (resumable) and <strong>Stop hunting</strong> (final).</li></ul>',28)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
